    // pending checkpoint object is disposed
    assertThat(checkpoint.isDisposed()).isTrue();
    // the now we should have a completed checkpoint
    assertThat(checkpointCoordinator.getNumberOfRetainedSuccessfulCheckpoints()).isOne();
    assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isZero();
    // the canceler should be removed now
    assertThat(manuallyTriggeredScheduledExecutor.getActiveScheduledTasks()).isEmpty();
    // validate that the subtasks states have registered their shared states.
    {
        verify(subtaskState1, times(1)).registerSharedStates(any(SharedStateRegistry.class), eq(checkpointId));
        verify(subtaskState2, times(2)).registerSharedStates(any(SharedStateRegistry.class), eq(checkpointId));
    }
    // validate that the relevant tasks got a confirmation message
    for (ExecutionVertex vertex : Arrays.asList(vertex1, vertex2)) {
        ExecutionAttemptID attemptId = vertex.getCurrentExecutionAttempt().getAttemptId();
        assertThat(gateway.getOnlyNotifiedCompletedCheckpoint(attemptId).checkpointId).isEqualTo(checkpointId);
    }
    CompletedCheckpoint success = checkpointCoordinator.getSuccessfulCheckpoints().get(0);
    assertThat(success.getJobId()).isEqualTo(graph.getJobID());
    assertThat(success.getCheckpointID()).isEqualTo(checkpoint.getCheckpointID());
    assertThat(success.getOperatorStates()).hasSize(2);
    // ---------------
    // trigger another checkpoint and see that this one replaces the other checkpoint
    // ---------------
    gateway.resetCount();
    checkpointCoordinator.triggerCheckpoint(false);
    manuallyTriggeredScheduledExecutor.triggerAll();
    long checkpointIdNew = checkpointCoordinator.getPendingCheckpoints().entrySet().iterator().next().getKey();
    checkpointCoordinator.receiveAcknowledgeMessage(new AcknowledgeCheckpoint(graph.getJobID(), attemptID1, checkpointIdNew), TASK_MANAGER_LOCATION_INFO);
    checkpointCoordinator.receiveAcknowledgeMessage(new AcknowledgeCheckpoint(graph.getJobID(), attemptID2, checkpointIdNew), TASK_MANAGER_LOCATION_INFO);
    assertThat(checkpointCoordinator.getNumberOfPendingCheckpoints()).isZero();
    assertThat(checkpointCoordinator.getNumberOfRetainedSuccessfulCheckpoints()).isOne();
    assertThat(manuallyTriggeredScheduledExecutor.getActiveScheduledTasks()).isEmpty();
    CompletedCheckpoint successNew = checkpointCoordinator.getSuccessfulCheckpoints().get(0);
    assertThat(successNew.getJobId()).isEqualTo(graph.getJobID());
    assertThat(successNew.getCheckpointID()).isEqualTo(checkpointIdNew);
    assertThat(successNew.getOperatorStates()).hasSize(2);
    assertThat(successNew.getOperatorStates().values().stream().allMatch(this::hasNoSubState)).isTrue();
    // validate that the relevant tasks got a confirmation message
    for (ExecutionVertex vertex : Arrays.asList(vertex1, vertex2)) {
        ExecutionAttemptID attemptId = vertex.getCurrentExecutionAttempt().getAttemptId();
        assertThat(gateway.getOnlyTriggeredCheckpoint(attemptId).checkpointId).isEqualTo(checkpointIdNew);
        assertThat(gateway.getOnlyNotifiedCompletedCheckpoint(attemptId).checkpointId).isEqualTo(checkpointIdNew);
    }
    checkpointCoordinator.shutdown();
}

