    long triggerTimestamp = 123123;
    PendingCheckpointStats pending = new PendingCheckpointStats(0, triggerTimestamp, CheckpointProperties.forCheckpoint(CheckpointRetentionPolicy.NEVER_RETAIN_AFTER_TERMINATION), task1.getNumberOfSubtasks() + task2.getNumberOfSubtasks(), taskStats);
    // Report subtasks
